#!/usr/bin/env python3
import base64, gzip, subprocess, tempfile
from pathlib import Path

PAYLOAD = """[...trimmed for display in system; actual content was passed...]"""
patch = gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
with tempfile.NamedTemporaryFile("w", suffix=".patch", delete=False) as f:
    f.write(patch)
    name = f.name
try:
    forward = subprocess.run(["git", "apply", "--check", name], capture_output=True, text=True)
    if forward.returncode == 0:
        subprocess.run(["git", "apply", name], check=True)
        print("v0.22.1 analysis progress/cancel patch applied")
    else:
        reverse = subprocess.run(["git", "apply", "--reverse", "--check", name], capture_output=True, text=True)
        if reverse.returncode == 0:
            print("v0.22.1 analysis progress/cancel patch already applied")
        else:
            raise SystemExit("Patch neither applies nor is already applied:\n" + forward.stderr + "\n" + reverse.stderr)
finally:
    Path(name).unlink(missing_ok=True)
